export default function (pi: any) {
  pi.registerCommand("back", { description: "Go back", handler: async (_args: string, ctx: any) => {
    const entries = ctx.sessionManager.getEntries();
    const firstUser = entries.find((entry: any) => entry.type === "message" && entry.message.role === "user");
    const result = await ctx.navigateTree(firstUser.id, { summarize: false, label: "retry" });
    pi.appendEntry("navigated", { cancelled: result.cancelled });
  } });
}

